use vstd::prelude::*;

verus! {
    //----------------------------------------------------------------
    // A tiny state type carrying an 8‐bit seed
    //----------------------------------------------------------------
    struct RandomState {
        seed: u8,
    }

    //----------------------------------------------------------------
    // Pure specification: given any u8 seed, map seed % 8
    // into one of {0.0,0.125,…,0.875}
    //----------------------------------------------------------------
    spec fn random_spec(seed: u8) -> f32 {
        match seed % 8 {
            0 => 0.0,
            1 => 0.125,
            2 => 0.25,
            3 => 0.375,
            4 => 0.5,
            5 => 0.625,
            6 => 0.75,
            _ => 0.875,  // covers 7
        }
    }

    //----------------------------------------------------------------
    // The implementation simply re‐computes the same mapping via
    // a small lookup table.  No preconditions needed.
    //----------------------------------------------------------------
    fn random(state: RandomState) -> (result: f32)
        ensures
            // It exactly matches our spec function
            result == random_spec(state.seed),
            // And hence is always in [0.0, 1.0)
            0.0f32 <= result && result < 1.0f32,
    {
        // compute index = seed % 8
        let idx: usize = (state.seed % 8) as usize;

        // static table of 8 equally‐spaced values
        let table: [f32; 8] =
            [0.0f32, 0.125f32, 0.25f32, 0.375f32,
             0.5f32, 0.625f32, 0.75f32, 0.875f32];

        // do the lookup
        let result = table[idx];
        result
    }
}

